CREATE OR REPLACE FUNCTION calculate_cpi(
    hist_sign SMALLINT,
    research_val INTEGER,
    cult_score SMALLINT,
    conserve_status VARCHAR(150)
) RETURNS NUMERIC AS $ $
DECLARE
    status_val INTEGER;
BEGIN
    -- Map conserve_status to status_val
    CASE conserve_status
        WHEN 'Excellent' THEN status_val := 1;
        WHEN 'Good' THEN status_val := 2;
        WHEN 'Fair' THEN status_val := 3;
        WHEN 'Poor' THEN status_val := 4;
        WHEN 'Critical' THEN status_val := 5;
        ELSE status_val := 0; -- Default value for unknown statuses
    END CASE;

    -- Calculate CPI using the provided formula
    RETURN ((hist_sign + research_val + cult_score) * (10 - status_val))::NUMERIC / 30;
END;
$ $ LANGUAGE plpgsql;

